const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

export function buildWelcome(row, unsubUrl) {
  const t = row.launch_list ? T.launch : T.newsletter;
  const a = `<a href="${esc(unsubUrl)}" style="color:#D9C6DE;text-decoration:underline;">Unsubscribe</a>.`;
  return { subject: t.subject, html: t.html.replace("@@UNSUB@@", a), text: t.text.replace("@@UNSUB@@", unsubUrl) };
}
